        From 6635a004c2676fe1f61ccfdf54fa52eab596362f Mon Sep 17 00:00:00 2001
From: Hans Beckerus <hans.beckerus at gmail.com>
Date: Sat, 22 Apr 2017 22:55:28 +0200
Subject: [PATCH] Fix an issue with volume consistency check

This patch fixes an issue with volume consistency check added
in d194e56552dda7abfabb6cab794af25c8c9751fc

Signed-off-by: Hans Beckerus <hans.beckerus at gmail.com>
---
 rar2fs.c | 9 +++++++--
 1 file changed, 7 insertions(+), 2 deletions(-)

diff --git a/rar2fs.c b/rar2fs.c
index 14ca4c3..0c39546 100644
--- a/rar2fs.c
+++ b/rar2fs.c
@@ -836,10 +836,14 @@ static int __check_rar_header(const char *arch)
         if (d.OpenResult) {
                 if (h)
                         RARCloseArchive(h);
+                free(last_arch);
+                last_arch = NULL;
                 return -1;
         }
         if (RARReadHeaderEx(h, &header))  {
                 RARCloseArchive(h);
+                free(last_arch);
+                last_arch = NULL;
                 return -1;
         }
         RARCloseArchive(h);
@@ -856,8 +860,9 @@ static int RARVolNameToFirstName_BUGGED(char *s, int vtype)
         int pos;

         RARVolNameToFirstName(s, vtype);
-        int n = get_vformat(s, !vtype, &len, &pos);
-        if (n == 1) {
+        if (!IS_RAR(s) && !IS_NNN(s))
+                return -1;
+        if (get_vformat(s, !vtype, &len, &pos) == 1) {
                 char *s_copy = strdup(s);
                 while (--len >= 0)
                         s_copy[pos+len] = '0';
-- 
